def transform(grid):
    """Extend each numbered marker along its fixed path; crossings spawn 4-rays."""
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    paths = []

    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == 1:
                # Two steps right, then one up.
                route = [(r, c + 1), (r, c + 2), (r - 1, c + 2)]
            elif color == 2:
                route = [(r, c - k) for k in range(1, 5)]
            elif color == 3:
                route = [(r + k, c) for k in range(1, 4)]
            elif color == 6:
                route = [(r - k, c) for k in range(1, 7)]
            else:
                continue

            visible = [(rr, cc) for rr, cc in route if 0 <= rr < h and 0 <= cc < w]
            for rr, cc in visible[:-1]:
                out[rr][cc] = 5
            if visible:
                rr, cc = visible[-1]
                # The far endpoint keeps the marker's color.
                out[rr][cc] = color
            paths.append(set(visible[:-1]))

    # A shared interior point of two trails becomes 4.
    crossings = set()
    for i in range(len(paths)):
        for j in range(i + 1, len(paths)):
            crossings.update(paths[i] & paths[j])
    for r, c in crossings:
        out[r][c] = 4

    # Each crossing sends a 4 trail diagonally down-left to the boundary.
    for r, c in crossings:
        k = 1
        while r + k < h and c - k >= 0:
            out[r + k][c - k] = 4
            k += 1
    return out
